/** V1 遗留数据指纹（V1 口径 sha256(JSON.stringify(模板))；与 V1 图库 metadata.workflowFingerprint 同源）。 */
export function v1LegacyFingerprint(): string {
  return createHash('sha256').update(JSON.stringify(V1_LEGACY_WORKFLOW), 'utf8').digest('hex');
}

/** database.ts v6 迁移落库的档案条目形状（与 WorkflowProfileRecord 字段对齐，isDefault 恒 true）。 */
export interface V1LegacyProfileEntry {
  id: string;
  name: string;
  revision: string;
  fingerprint: string;
  confirmedModes: string[];
  isDefault: boolean;
  workflow: ApiWorkflow;
  analysis: WorkflowAnalysis;
}

/**
 * 构建 V1 迁移档案条目（用户裁决 Q5：不补写标记、不做兼容——仅数据搬运）：
 * 原始 JSON 深拷贝入库、无 [params] 标记参数（parameters 空 → 不可生成）、
 * LoRA 按节点类型离线扫描保留、sampler/scheduler 只读信息按模板现值读取、
 * suggestedModes 留空（解析器口径：无标记参数即无建议模式）。
 */
export function buildV1LegacyProfileEntry(): V1LegacyProfileEntry {
  const workflow = structuredClone(V1_LEGACY_WORKFLOW);
  const fingerprint = v1LegacyFingerprint();
  let sampler: string | null = null;
  let scheduler: string | null = null;
  for (const node of Object.values(workflow)) {
    const samplerName = node.inputs.sampler_name;
    const schedulerName = node.inputs.scheduler;
    if (typeof samplerName === 'string' && typeof schedulerName === 'string') {
      sampler = samplerName;
      scheduler = schedulerName;
      break;
    }
  }
  const analysis: WorkflowAnalysis = {
    revision: `sha256:${fingerprint}`,
    fingerprint,
    parameters: [],
    loras: scanLoras(workflow),
    aiExpansionModes: ['none', 'custom_llm'],
    suggestedModes: [],
    issues: [{
      nodeId: null,
      severity: 'warning',
      message: 'V1 迁移档案：旧版模板无 [params] 标记参数，仅保留档案与历史关联，不可生成；请在电脑控制台或 App 重新上传 V1.1 模板。'
    }],
    readonlyInfo: { sampler, scheduler }
  };
  return {
    id: `wf_${randomUUID()}`,
    name: 'V1 旧工作流（迁移）',
    revision: analysis.revision,
    fingerprint,
    confirmedModes: ['professional'],
    isDefault: true,
    workflow,
    analysis
  };
}
